/** How an `.asni` file is made. There are no options yet. */
export interface CompileOptions {}

/** What a compiled module has. */
export interface ModuleSummary {
  name: string;
  types: number;
  objectClasses: number;
}

/**
 * Something that is valid ASN.1 but likely to cause trouble. The kind is
 * `RecursiveType` for now, and the message tells where, as that of an
 * error does.
 */
export interface Warning {
  kind: string;
  message: string;
}

/** Loads the WebAssembly, which the other functions do too. */
export function ready(): Promise<void>;

/**
 * Compiles the text of a specification, of one module or more, to the
 * contents of an `.asni` file. Throws an `Error` named `ParseError` or
 * `CompileError` that tells where, or a `TypeError` for wrong options.
 */
export function compile(specification: string, options?: CompileOptions): Promise<Uint8Array>;

/**
 * The same as `compile()`, and tells what the modules have and what is
 * likely to cause trouble, in the order of the types.
 */
export function compileWithSummary(
  specification: string,
  options?: CompileOptions,
): Promise<{ asni: Uint8Array; modules: ModuleSummary[]; warnings: Warning[] }>;

/**
 * What a schema is of: a JSON Schema (draft 2020-12) of JER, an XML
 * Schema (XSD 1.0) of BASIC-XER or a DTD of BASIC-XER.
 */
export type SchemaFormat = 'json-schema' | 'xsd' | 'dtd';

/** What `schema()` makes. */
export interface SchemaOptions {
  /** `json-schema` if not given. */
  format?: SchemaFormat;
  /**
   * The types of which the values are the documents, as `Type` or
   * `Module.Type`, with those they refer to. Every type if not given.
   */
  types?: string | string[];
  /**
   * Leave out what a schema can not tell, as an `ANY`, and what refers
   * to it, rather than fail. A type given in `types` is never left out.
   */
  skipUnsupported?: boolean;
  /**
   * The ASN.1 text the `.asni` file is compiled from. The pragma
   * `--@ schema_comment = ...` of the modules of the types is then the
   * comment of the schema, rather than `schema generated by asnkit`.
   */
  specification?: string;
}

/** A schema, and the types it leaves out with `skipUnsupported`. */
export interface Schema {
  text: string;
  /** How many types it is of. */
  types: number;
  skipped: { type: string; reason: string }[];
}

/**
 * Makes what the values of the types of the contents of an `.asni` file
 * are in a text codec, as `asnkitcc schema` does. Throws an `Error` named
 * `SchemaError` that tells where in the types for what a schema can not
 * tell, or a `TypeError` for wrong options.
 */
export function schema(asni: Uint8Array, options?: SchemaOptions): Promise<Schema>;

/** Parses the text of a specification to the contents of an `.asnst` file. */
export function parse(specification: string): Promise<Uint8Array>;

/** Compiles the ASN.1 file with this path, read as UTF-8. Node.js only. */
export function compileFile(path: string, options?: CompileOptions): Promise<Uint8Array>;

/** The version of the compiler. In a browser, once `ready()` is done. */
export function version(): string;
